  const bgtTexts=__BUDGET_TEXTS__;
  Object.assign(state,{bgtHome:true,bgtUsed:3286.5,bgtAmount:5000,bgtMode:'normal',bgtReadonly:false,bgtCurrency:'CNY'});
  const bgtColor=ratio=>ratio>=.9?'var(--bgt-error)':ratio>=.7?'#d79b27':'#25856d';
  const bgtSymbol=()=>state.bgtCurrency==='USD'?'$':'¥';
  const bgtText=(key,value)=>bgtTexts[key].replace(/\{[^}]+\}/g,String(value));
  function bgtTotal(){
    const ratio=state.bgtUsed/state.bgtAmount,remaining=state.bgtAmount-state.bgtUsed,symbol=bgtSymbol();
    return surface(`<div class="bgt-heading"><h3>${esc(bgtTexts.budgetMonthlyBudget)}</h3>${state.bgtReadonly?'':btn('bgt-total',bgtTexts.commonEdit,bgtTexts.commonEdit,'bgt-edit')}</div><div class="bgt-d104-meta"><div><small>${esc(bgtTexts.budgetUsed)} · ${state.bgtCurrency}</small><strong>${symbol}${money(state.bgtUsed)}</strong></div><div><small>${esc(bgtTexts.budgetRemaining)}</small><b style="color:${remaining<0?'var(--bgt-error)':'inherit'}">${symbol}${money(remaining)}</b></div></div><div class="bgt-track bgt-d104-progress" style="--bgt-color:${ratio<.7?'var(--bc-accent)':bgtColor(ratio)}" role="img" aria-label="${esc(bgtTexts.budgetUsed)} ${Math.round(ratio*100)}%"><i style="width:${Math.min(100,Math.max(0,ratio*100))}%"></i></div><div class="bgt-d104-label"><span style="color:${bgtColor(ratio)}">${esc(bgtTexts.budgetUsed)} ${Math.round(ratio*100)}%</span><span>${esc(bgtTexts.budgetTypeTotalLabel)} ${symbol}${money(state.bgtAmount)}</span></div><div class="bgt-bottom"><div><small>${esc(bgtText('budgetDaysRemaining',11))}</small><strong>${esc(bgtText('budgetDailyAvailable',symbol+Math.round(Math.max(0,remaining)/11)))}</strong></div></div>`,'bgt-total-card d104-live-card');
  }
  function bgtCategories(){
    const symbol=bgtSymbol(),rows=[['餐饮','utensils',1199.57,1500],['饮品','custom',215,100],['交通','train-front',525.84,800]];
    return surface(`<div class="bgt-heading"><h3>${esc(bgtTexts.budgetCategoryBudgets)}</h3>${state.bgtReadonly?'':btn('bgt-category-add',bgtTexts.commonAdd,bgtTexts.commonAdd,'bgt-edit')}</div>${rows.map(([name,image,used,total])=>btn('bgt-category',`<span class="bgt-category-icon">${image==='custom'?'<img src="assets/category-coffee.png" alt="自定义图片">':icon(image)}</span><span class="bgt-category-copy"><span><b>${esc(name)}</b><strong style="color:${bgtColor(used/total)}">${Math.round(used/total*100)}%</strong></span><span class="bgt-track" style="--bgt-color:${bgtColor(used/total)}"><i style="width:${Math.min(100,used/total*100)}%"></i></span><small>${symbol}${used.toFixed(0)} / ${symbol}${total.toFixed(0)}</small></span>`,name,'bgt-category',state.bgtReadonly?'disabled':'')).join('')}`,'bgt-category-card');
  }
  function bgtPage(){
    const empty=state.bgtMode==='empty';
    const contents=state.bgtMode==='loading'?'<div class="bgt-empty" role="status">正在读取预算…</div>':state.bgtMode==='error'?`<div class="bgt-empty">${icon('circle-alert')}<p>Error: 预算读取失败</p>${btn('bgt-retry',bgtTexts.v4RecordingRetry,bgtTexts.v4RecordingRetry,'bc-primary')}</div>`:empty?`<div class="bgt-empty">${icon('wallet')}<p>${esc(bgtTexts.budgetEmptyHint)}</p>${state.bgtReadonly?'':btn('bgt-add',bgtTexts.budgetAddTotal,bgtTexts.budgetAddTotal,'bc-primary')}</div>`:bgtTotal()+bgtCategories()+surface(btn('bgt-home',`<span>${icon('eye')}${esc(bgtTexts.budgetShowOnHome)}</span><span class="bc-switch"></span>`,bgtTexts.budgetShowOnHome,'bgt-home',`role="switch" aria-checked="${state.bgtHome}"`),'bc-menu-card');
    return `<div class="bgt-shell">${subhead(bgtTexts.budgetTitle,state.bgtReadonly?'':'bgt-add','plus').replace('更多操作',bgtTexts.commonAdd)}<div class="bgt-scroll ${empty?'bgt-center':''}">${contents}</div></div>`;
  }
  const bgtScenes=[['budget','预算管理','normal',false,3286.5,'CNY'],['budget-warning','预算 · 接近上限','normal',false,3750,'CNY'],['budget-danger','预算 · 即将超支','normal',false,4750,'CNY'],['budget-exceeded','预算 · 超支负剩余','normal',false,6250,'CNY'],['budget-empty','预算 · 空态','empty',false,0,'CNY'],['budget-readonly','预算 · 共享成员只读','normal',true,3286.5,'CNY'],['budget-empty-readonly','预算 · 共享成员空态','empty',true,0,'CNY'],['budget-loading','预算 · 读取中','loading',false,0,'CNY'],['budget-error','预算 · 读取失败','error',false,0,'CNY'],['budget-usd','预算 · 美元账本','normal',false,215.2,'USD']];
  function bgtPrepare(key){const scene=bgtScenes.find(s=>s[0]===key);if(scene&&state.bgtScene!==key)Object.assign(state,{bgtScene:key,bgtMode:scene[2],bgtReadonly:scene[3],bgtUsed:scene[4],bgtCurrency:scene[5],bgtAmount:scene[5]==='USD'?200:5000});}
  budget=function(){bgtPrepare('budget');return bgtPage();};
  for(const[key,title]of bgtScenes)fDefine(key,title,'分类标签与预算','budget/budget_page.dart',bgtPage);
  const bgtPreviousRender=fRender;fRender=function(key){if(bgtScenes.some(s=>s[0]===key)){bgtPrepare(key);return bgtPage();}return bgtPreviousRender(key);};
  root.addEventListener('click',event=>{const element=event.target.closest('[data-action]');if(!element?.dataset.action.startsWith('bgt-'))return;event.preventDefault();event.stopImmediatePropagation();const action=element.dataset.action;if(action==='bgt-home'){state.bgtHome=!state.bgtHome;render();}else if(action==='bgt-retry'){state.bgtMode='normal';state.bgtUsed=3286.5;render();}else if(!state.bgtReadonly&&['bgt-total','bgt-category','bgt-add','bgt-category-add'].includes(action))navigate('flow-budget-edit');},true);

  const bgtAfter=qAfterRender;qAfterRender=function(){bgtAfter();for(const el of phone.querySelectorAll('.bgt-remaining strong,.bgt-bottom>div:first-child strong,.bgt-ring b')){el.style.fontSize='';if(el.scrollWidth>el.clientWidth)el.style.fontSize=parseFloat(getComputedStyle(el).fontSize)*el.clientWidth/el.scrollWidth+'px';}};
